CREATE TABLE paid_accounts (account_id TEXT PRIMARY KEY NOT NULL, authority BLOB NOT NULL, disabled INTEGER NOT NULL) STRICT;
CREATE TABLE paid_tasks (account_id TEXT NOT NULL, task_id TEXT NOT NULL, authority BLOB NOT NULL, PRIMARY KEY(account_id, task_id), FOREIGN KEY(account_id) REFERENCES paid_accounts(account_id)) STRICT;
CREATE TABLE paid_prices (account_id TEXT NOT NULL, provider_id TEXT NOT NULL, model_id TEXT NOT NULL, price BLOB NOT NULL, PRIMARY KEY(account_id, provider_id, model_id), FOREIGN KEY(account_id) REFERENCES paid_accounts(account_id)) STRICT;
CREATE TABLE paid_reservations (reservation_id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL, task_id TEXT NOT NULL, request_digest TEXT NOT NULL, provider_id TEXT NOT NULL, model_id TEXT NOT NULL, operation TEXT NOT NULL, cost_micros INTEGER NOT NULL, input_units INTEGER NOT NULL, output_units INTEGER NOT NULL, state TEXT NOT NULL, created_at REAL NOT NULL, observed_input INTEGER, observed_output INTEGER, UNIQUE(account_id, task_id, request_digest, provider_id, model_id, operation), FOREIGN KEY(account_id,task_id) REFERENCES paid_tasks(account_id,task_id)) STRICT;
